module benchmark/solution

import std/list (sortBy, length, nth)
import std/option (Some, None)

pure func compareInts(a: int, b: int) -> int =
  if a < b then -1 else if a > b then 1 else 0

pure func median(xs: [int]) -> int {
  let sorted = sortBy(compareInts, xs);
  match nth(sorted, (length(sorted) - 1) / 2) {
    Some(value) => value,
    None => 0
  }
}

export func main() -> () ! {IO} {
  println(show(median([7, 2, 5, 1, 9, 4, 8])));
  println(show(median([10, 20, 30, 40])))
}

